using Servicio.RetazoMarket.Business.DTOs.Producto;
namespace Servicio.RetazoMarket.Business.Validators;public static class ProductoMarketplaceValidator {public static IReadOnlyCollection<string> Validar(ProductoMarketplaceFiltroRequest r){var e=new List<string>();if(r is null)return ["El filtro no puede ser nulo."];if(!string.IsNullOrWhiteSpace(r.es_personalizable)&&r.es_personalizable.Trim().ToUpperInvariant() is not("S" or "N"))e.Add("El indicador personalizable debe ser S o N.");if(!string.IsNullOrWhiteSpace(r.tiene_descuentos)&&r.tiene_descuentos.Trim().ToUpperInvariant() is not("S" or "N"))e.Add("El indicador de descuentos debe ser S o N.");if(r.precio_minimo<0||r.precio_maximo<0||r.precio_minimo>r.precio_maximo)e.Add("El rango de precios no es válido.");if(r.page_number<=0)e.Add("El número de página debe ser mayor que cero.");if(r.page_size<=0||r.page_size>100)e.Add("El tamaño de página debe estar entre 1 y 100.");return e;}}
